"use client";

import {
  Background,
  Controls,
  MiniMap,
  ReactFlow,
  addEdge,
  applyNodeChanges,
  applyEdgeChanges,
  type Connection,
  type Edge,
  type Node,
  type OnConnect,
  type NodeChange,
  type EdgeChange,
} from "@xyflow/react";

import "@xyflow/react/dist/style.css";

import { useCallback, useMemo, useState } from "react";
import SystemNode, {
  type SystemNodeData,
} from "./SystemNode";
import ConnectionModal, {
  type ConnectionData,
} from "./ConnectionModal";

type ArchitectureNode = Node<SystemNodeData>;

const initialNodes: ArchitectureNode[] = [
  {
    id: "power",
    type: "system",
    position: {
      x: 100,
      y: 180,
    },
    data: {
      label: "Power System",
      category: "Electrical",
      description:
        "Generates, stores, and distributes electrical power.",
    },
  },
  {
    id: "sensors",
    type: "system",
    position: {
      x: 450,
      y: 80,
    },
    data: {
      label: "Sensor System",
      category: "Sensors",
      description:
        "Collects information about the environment and system state.",
    },
  },
  {
    id: "computing",
    type: "system",
    position: {
      x: 800,
      y: 180,
    },
    data: {
      label: "Computing System",
      category: "Computing",
      description:
        "Processes sensor data and runs system software.",
    },
  },
  {
    id: "control",
    type: "system",
    position: {
      x: 1150,
      y: 300,
    },
    data: {
      label: "Control System",
      category: "Control",
      description:
        "Converts commands into actions and controls actuators.",
    },
  },
];

const initialEdges: Edge[] = [
  {
    id: "power-computing",
    source: "power",
    target: "computing",
    label: "Power",
    type: "smoothstep",
  },
  {
    id: "sensor-computing",
    source: "sensors",
    target: "computing",
    label: "Sensor Data",
    type: "smoothstep",
  },
  {
    id: "computing-control",
    source: "computing",
    target: "control",
    label: "Control",
    type: "smoothstep",
  },
];

export default function Architecture() {
  const [nodes, setNodes] =
    useState<ArchitectureNode[]>(initialNodes);

  const [edges, setEdges] =
    useState<Edge[]>(initialEdges);

  const [connectionModalOpen, setConnectionModalOpen] =
    useState(false);

  const [pendingConnection, setPendingConnection] =
    useState<Connection | null>(null);

  const nodeTypes = useMemo(
    () => ({
      system: SystemNode,
    }),
    []
  );

  const onConnect: OnConnect = useCallback(
    (connection) => {
      setPendingConnection(connection);
      setConnectionModalOpen(true);
    },
    []
  );

  function createConnection(data: ConnectionData) {
    if (!pendingConnection) {
      return;
    }

    const source = nodes.find(
      (node) => node.id === pendingConnection.source
    );

    const target = nodes.find(
      (node) => node.id === pendingConnection.target
    );

    if (!source || !target) {
      return;
    }

    const newEdge: Edge = {
      id: crypto.randomUUID(),
      source: pendingConnection.source!,
      target: pendingConnection.target!,
      label: `${getConnectionLabel(data.type)}${
        data.protocol
          ? ` · ${data.protocol}`
          : ""
      }`,
      type: "smoothstep",
      data,
    };

    setEdges((current) =>
      addEdge(newEdge, current)
    );

    setPendingConnection(null);
    setConnectionModalOpen(false);
  }

  function addSystem() {
    const id = crypto.randomUUID();

    const newNode: ArchitectureNode = {
      id,
      type: "system",
      position: {
        x: 300 + Math.random() * 500,
        y: 200 + Math.random() * 300,
      },
      data: {
        label: "New System",
        category: "Other",
        description:
          "Define this subsystem.",
      },
    };

    setNodes((current) => [
      ...current,
      newNode,
    ]);
  }

  return (
    <div className="relative h-full w-full overflow-hidden bg-[#0b0d10]">
      <div className="absolute left-5 top-5 z-10">
        <div className="rounded-xl border border-white/10 bg-[#111419]/95 px-4 py-3 shadow-xl backdrop-blur">
          <h2 className="text-sm font-semibold">
            System Architecture
          </h2>

          <p className="mt-1 text-xs text-white/40">
            Connect systems and define how information,
            power, and control flow through the project.
          </p>
        </div>
      </div>

      <div className="absolute right-5 top-5 z-10">
        <button
          onClick={addSystem}
          className="rounded-lg bg-white px-4 py-2 text-sm font-medium text-black shadow-lg hover:bg-white/90"
        >
          + Add System
        </button>
      </div>

      <ReactFlow
        nodes={nodes}
        edges={edges}
        nodeTypes={nodeTypes}
        onNodesChange={(changes: NodeChange[]) => {
  setNodes((current) =>
    applyNodeChanges(changes, current)
  );
        }}
        onEdgesChange={(changes: EdgeChange[]) => {
  setEdges((current) =>
    applyEdgeChanges(changes, current)
  );
        }}
        onConnect={onConnect}
        fitView
        colorMode="dark"
        deleteKeyCode={["Backspace", "Delete"]}
      >
        <Background gap={24} size={1} />

        <Controls />

        <MiniMap />
      </ReactFlow>

      <ConnectionModal
        open={connectionModalOpen}
        sourceName={
          nodes.find(
            (node) =>
              node.id === pendingConnection?.source
          )?.data.label ?? ""
        }
        targetName={
          nodes.find(
            (node) =>
              node.id === pendingConnection?.target
          )?.data.label ?? ""
        }
        onClose={() => {
          setPendingConnection(null);
          setConnectionModalOpen(false);
        }}
        onSubmit={createConnection}
      />
    </div>
  );
}

function getConnectionLabel(
  type: ConnectionData["type"]
) {
  switch (type) {
    case "power":
      return "Power";

    case "communication":
      return "Communication";

    case "sensor_data":
      return "Sensor Data";

    case "control":
      return "Control";

    case "mechanical":
      return "Mechanical";

    case "thermal":
      return "Thermal";
  }
}